# المحتوى من gen_prime_summary.py وprime_slides.py (كتاب الطالب ص٢٨–٢٩، دليل المعلم).
import os
exec(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'lesson_video.py'), encoding='utf-8').read())
AR = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')
def a(n): return str(n).translate(AR)
def K(t): return f'<b style="color: #C2410C">{t}</b>'
PRIMES = [p for p in range(2, 101) if all(p % d for d in range(2, int(p ** .5) + 1))]
def SIEVE(upto=100, h=330):   # غربال إراتوستينس: الأعداد الأولية حتى ١٠٠ مظلَّلة
    cell = h // 10
    rows = ''.join('<div style="display: flex; direction: rtl">' + ''.join(
        f'<span style="width: {cell}px; height: {cell}px; display: flex; align-items: center; justify-content: center; font-size: {cell * .45:.0f}px; border: 1px solid #C9D6E8; '
        + ('background: #FFE08A; color: #14305C; font-weight: 800' if n in PRIMES else 'color: #A9B6CC') + f'">{a(n)}</span>' for n in range(r * 10 + 1, r * 10 + 11)) + '</div>' for r in range(10))
    return f'<span style="display: inline-flex; flex-direction: column; vertical-align: middle; border: 2px solid #14305C">{rows}</span>'
def TREE(n, steps, h=280):   # شجرة العوامل: العامل الأولي في دائرة (يميناً) ونكمل مع الآخر (يساراً)
    W, dy, x, y, o = 80 * (len(steps) + 1), 60, 80 * len(steps) + 30, 34, []
    o.append(f'<text x="{x}" y="{y}">{a(n)}</text>')
    for p, m in steps:
        xl, xr, y2 = x - 46, x + 40, y + dy
        o.append(f'<line x1="{x}" y1="{y + 8}" x2="{xl}" y2="{y2 - 22}"/><line x1="{x}" y1="{y + 8}" x2="{xr}" y2="{y2 - 22}"/>')
        o.append(f'<circle cx="{xr}" cy="{y2 - 9}" r="20" fill="#FFE08A"/><text x="{xr}" y="{y2}">{a(p)}</text>')
        o.append((f'<circle cx="{xl}" cy="{y2 - 9}" r="20" fill="#FFE08A"/>' if m in PRIMES else '') + f'<text x="{xl}" y="{y2}">{a(m)}</text>')
        x, y = xl, y2
    return (f'<svg viewBox="0 0 {W + 40} {y + 22}" style="height: {h}px; width: auto; vertical-align: middle; stroke: #14305C; stroke-width: 3; fill: none; '
            f'font-family: Cairo; font-size: 28px; font-weight: 800; text-anchor: middle">{"".join(o).replace("<text", "<text fill=\"#14305C\" stroke=\"none\"")}</svg>')
